function readPaging(query) {
  const params = new URLSearchParams(query);
  const limitText = params.get("limit") ?? "10";
  const offsetText = params.get("offset") ?? "0";
  if (!/^[0-9]{1,6}$/.test(limitText) || !/^[0-9]{1,6}$/.test(offsetText)) {
    return { error: "bad paging" };
  }
  const limit = Number(limitText);
  if (limit < 1 || limit > 50) return { error: "bad paging" };
  return { limit, offset: Number(offsetText) };
}

for (const query of ["", "limit=5&offset=10", "limit=500", "offset=-1", "limit=abc"]) {
  console.log(JSON.stringify(readPaging(query)));
}

