function kind(status) {
  const family = Math.floor(status / 100);
  if (family === 2) return "success";
  if (family === 4) return "client error";
  if (family === 5) return "server error";
  return "other";
}

for (const status of [201, 204, 404, 413, 500, 302]) {
  console.log(status, kind(status));
}
